SET NAMES utf8mb4;

UPDATE policies
SET title = '商务部等九部门关于推动农村电商高质量发展的实施意见',
    summary = '围绕农村电商高质量发展，提出用5年时间培育约100个领跑县、1000家县域数字流通龙头企业、1000个直播电商基地和10000名带头人。',
    content = '<h3>一、政策目标</h3><p>该意见由商务部等九部门联合印发，提出用5年时间基本建成设施完善、主体活跃、流通顺畅、服务高效的农村电商服务体系，持续增强农产品上行和农民增收带动能力。</p><h3>二、支持重点</h3><ul><li>推进县乡村三级电商服务与物流配送体系升级，完善冷链仓储、共同配送和服务站点建设。</li><li>重点培育约100个农村电商“领跑县”、1000家县域数字流通龙头企业、1000个县域直播电商基地。</li><li>加强主体培育和人才建设，计划培育10000名左右农村电商带头人，提升就业创业带动能力。</li><li>完善品牌打造、质量分级和供应链协同机制，推动农产品标准化、品牌化和数字化发展。</li></ul><h3>三、实施要求</h3><p>各地需围绕县域商业体系建设、农村寄递物流和数字乡村发展统筹推进，形成“设施建设+主体培育+品牌推广”协同机制。</p><h3>四、申报提示</h3><p>建议重点准备县域电商基础、物流配套、主体培育方案和年度带农数据，突出项目可落地性与持续运营能力。</p>'
WHERE policies_id = 'demo_policy_20260324_01';

UPDATE policies
SET title = '北京市关于促进农产品市场发展的若干措施',
    summary = '围绕农产品市场建设和流通保障，重点支持交易场地、冷链仓储、智慧市场、社区菜店等6类方向，强化城市保供能力。',
    content = '<h3>一、政策目标</h3><p>该政策围绕北京市现代商贸流通体系试点建设，重点提升农产品市场承载能力、流通效率和生活必需品保供水平，增强城市消费市场对优质农产品的承接能力。</p><h3>二、支持重点</h3><ul><li>支持农产品批发市场交易场地、仓储冷链、分拣加工、配送检测等设施设备建设和改造。</li><li>支持菜市场标准化升级，配备智慧管理系统、电子秤、电子大屏和智能监控等数字化设备。</li><li>支持综合物流园区、冷链配送中心、电商大仓和前置仓建设，提升仓储、分拣和温控能力。</li><li>支持超市、社区菜店、便利店等直营网点建设，形成更加完善的便民服务网络。</li><li>政策明确了6类重点支持方向，并以京商流通字〔2025〕9号文件形式组织项目申报。</li></ul><h3>三、实施要求</h3><p>项目建设要兼顾保供、便民、标准化和数字化要求，形成可考核、可复制的流通服务提升方案。</p><h3>四、申报提示</h3><p>建议提前准备项目方案、投资预算、场地材料和设备清单，并重点说明对市场升级和保供稳价的带动作用。</p>'
WHERE policies_id = 'demo_policy_20260324_02';

UPDATE policies
SET title = '宁夏“数商兴农年”活动工作安排',
    summary = '围绕数商兴农活动开展，重点支持电商培训、直播推介和县域主体培育。相关活动中可实现5000余场直播、9.1亿元农产品网络零售额。',
    content = '<h3>一、政策目标</h3><p>该类活动以“数商兴农”为抓手，围绕宁夏特色农产品上行、县域电商主体培育和线上促消费活动展开，提升农村电商发展质量与品牌影响力。</p><h3>二、支持重点</h3><ul><li>组织农户、电商从业者和合作社负责人参与电商运营、直播带货和品牌推广培训。</li><li>开展线上促销、直播推介、区域品牌宣传和特色农产品展销活动，推动产销精准对接。</li><li>依托电商公服中心、直播基地和平台专区开展助农活动，强化“平台+基地+品牌”协同。</li><li>从官方公开活动成效看，相关促消费活动可带动5000余场直播、农产品网络零售额达9.1亿元，具备较强示范性。</li></ul><h3>三、实施要求</h3><p>各地需结合本地特色产业和消费节点统筹安排活动计划，明确组织主体、宣传方式和绩效统计口径。</p><h3>四、申报提示</h3><p>建议重点准备活动方案、直播场次、销售数据、培训记录和品牌传播效果材料，便于后续核验与评估。</p>'
WHERE policies_id = 'demo_policy_20260324_03';

UPDATE policies
SET title = '科技特派员助力乡村振兴服务案例',
    summary = '围绕科技服务下沉和成果转化，相关案例中已建设15个示范基地、推广82项技术模式、培训5255人次，技术支撑效果较为明显。',
    content = '<h3>一、政策目标</h3><p>科技特派员服务强调把农业技术、种养方案和产业指导送到田间地头，提升基层经营主体的技术应用能力和产业发展质量。</p><h3>二、支持重点</h3><ul><li>围绕粮油、果蔬、中药材和地方特色产业开展现场指导、技术培训和成果转化服务。</li><li>依托示范基地、工作站和专家团队建立常态化服务机制，增强基层技术支撑能力。</li><li>根据湖北公开案例数据，已建设示范基地15个，推广新技术、新品种和新模式82项，全年培训15次、累计培训5255人次。</li><li>同步实现科技成果转化5项、解决技术问题1764次，并新增5个省级科技特派员工作站。</li></ul><h3>三、实施要求</h3><p>坚持“技术服务+示范推广+人才培养”联动推进，突出对地方特色产业和经营主体的持续帮扶。</p><h3>四、申报提示</h3><p>建议重点准备技术需求清单、示范基地情况、服务记录和培训成效材料，体现服务过程和成果转化效果。</p>'
WHERE policies_id = 'demo_policy_20260324_04';

UPDATE policies
SET title = '促进农产品消费实施方案',
    summary = '围绕扩大农产品消费、提升优质供给和创新消费场景，由10部门联合部署绿色优质供给、产销衔接、电商平台协同和品牌引领等重点任务。',
    content = '<h3>一、政策目标</h3><p>该方案由农业农村部等10部门联合发布，围绕释放多样化、品质化、差异化消费潜力，推动农产品消费提质扩容，进一步增强市场活力和品牌影响力。</p><h3>二、支持重点</h3><ul><li>优化供给端，围绕“三品一标”、品质评价和质量分级，提升绿色优质农产品供给能力。</li><li>创新流通端，促进产供销精准衔接，拓宽节庆展会、城乡市场和电商平台等多元消费场景。</li><li>激活市场端，强化品牌引领、营养健康消费宣传和农文旅融合，提升农产品消费吸引力。</li><li>加强部门协同，完善财政金融支持和全链条监管机制，形成从生产到消费的协同推进体系。</li></ul><h3>三、实施要求</h3><p>地方在落实时需兼顾绿色优质供给、场景创新和品牌培育，形成“供给优化+渠道拓展+消费引导”联动模式。</p><h3>四、申报提示</h3><p>建议围绕品牌建设、渠道活动、优质产品供给和消费促进成效准备材料，突出政策执行后的市场带动作用。</p>'
WHERE policies_id = 'demo_policy_20260324_05';
